  function dateText(value,language){const tag=language==='zh-Hant'?'zh-TW':language==='zh-Hans'?'zh-CN':language;try{return new Intl.DateTimeFormat(tag,{year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(`${value}T12:00:00+08:00`))}catch(_){return value.replaceAll('-','.')}}
  function cssUrl(){const script=document.currentScript?.src||new URL('assets/home-media-reports-20260903.js',document.baseURI).href;return new URL('home-media-reports-20260903.css?v=20260904-policy-1',script).href}
