  function injectNav(text){const nav=document.querySelector('.art-header .container.nav > nav');if(!nav||nav.querySelector('[data-cpa-news-nav]'))return;const link=document.createElement('a');link.href=text.index;link.className='cpa-news-nav-link';link.dataset.cpaNewsNav='true';link.textContent=text.nav;link.setAttribute('aria-label',text.nav);const first=nav.querySelector('.social-case-nav');if(first)nav.insertBefore(link,first);else nav.appendChild(link)}
  function visual(item,language,text){const box=document.createElement('div');box.className='home-media-visual';const img=document.createElement('img');img.className='home-media-pastel-art';img.src=item.image;img.alt=item.alt[language];img.loading=item.priority===1?'eager':'lazy';img.decoding='async';const label=document.createElement('span');label.className='home-media-pastel-label';label.textContent=text.eyebrow;box.append(img,label);return box}
  function card(item,language,text){const url=typeof item.article==='string'?item.article:item.article[language];const el=document.createElement('article');el.className='home-media-report-card';el.dataset.date=item.date;el.setAttribute('role','listitem');el.appendChild(visual(item,language,text));const body=document.createElement('div');body.className='home-media-report-copy';const meta=document.createElement('div');meta.className='home-media-report-meta';const time=document.createElement('time');time.className='home-media-report-date';time.dateTime=item.date;time.textContent=dateText(item.date,language);const publisher=document.createElement('span');publisher.textContent=item.publisher[language];meta.append(time,publisher);const h3=document.createElement('h3');const title=document.createElement('a');title.href=url;title.textContent=item.headline[language];h3.appendChild(title);const summary=document.createElement('p');summary.textContent=item.summary[language];const source=document.createElement('span');source.className='home-media-report-source';source.textContent=item.publisher[language];const action=document.createElement('a');action.className='home-media-report-action';action.href=url;action.textContent=`${text.action} →`;body.append(meta,h3,summary,source,action);el.appendChild(body);return el}
  function init(){const language=getLocale(),text=sectionCopy[language]||sectionCopy['zh-Hant'];addStyles();injectNav(text);if(document.getElementById('home-media-reports'))return;const latest=document.getElementById('news-flash');if(!latest)return;const section=document.createElement('section');section.id='home-media-reports';section.className='home-media-reports-section';section.setAttribute('aria-labelledby','homeMediaReportsTitle');const container=document.createElement('div');container.className='container';const header=document.createElement('div');header.className='home-news-stream-head home-flash-head home-media-reports-head';const headCopy=document.createElement('div');const eyebrow=document.createElement('div');eyebrow.className='art-eyebrow dark';eyebrow.textContent=text.eyebrow;const h2=document.createElement('h2');h2.id='homeMediaReportsTitle';h2.textContent=text.title;const desc=document.createElement('p');desc.textContent=text.description;headCopy.append(eyebrow,h2,desc);const all=document.createElement('a');all.className='home-media-all-link';all.href=text.index;all.textContent=`${text.all} →`;header.append(headCopy,all);const viewport=document.createElement('div');viewport.className='home-media-report-viewport';viewport.setAttribute('role','region');viewport.setAttribute('aria-label',text.title);viewport.tabIndex=0;const track=document.createElement('div');track.className='home-media-report-track';track.setAttribute('role','list');[...reports].sort((a,b)=>Date.parse(`${b.date}T12:00:00+08:00`)-Date.parse(`${a.date}T12:00:00+08:00`)||a.priority-b.priority).forEach(item=>track.appendChild(card(item,language,text)));viewport.appendChild(track);const note=document.createElement('p');note.className='home-media-report-note';note.textContent=text.note;container.append(header,viewport,note);section.appendChild(container);latest.insertAdjacentElement('afterend',section);if(location.hash==='#home-media-reports')requestAnimationFrame(()=>section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}))}
